import{_ as e,o as a,c as n,al as r}from"./chunks/framework.7vp1BMOE.js";const h=JSON.parse('{"title":"파일 및 코드 설치개발자 환경 설정 (툴체인)","description":"","frontmatter":{},"headers":[],"relativePath":"ko/dev_setup/dev_env.md","filePath":"ko/dev_setup/dev_env.md"}'),i={name:"ko/dev_setup/dev_env.md"};function l(d,t,s,o,c,u){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="파일-및-코드-설치개발자-환경-설정-툴체인" tabindex="-1">파일 및 코드 설치개발자 환경 설정 (툴체인) <a class="header-anchor" href="#파일-및-코드-설치개발자-환경-설정-툴체인" aria-label="Permalink to &quot;파일 및 코드 설치개발자 환경 설정 (툴체인)&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You only need a toolchain if you want to <strong>modify and build</strong> PX4 from source. If you just want to run PX4 simulation without changing the code, use a pre-built <a href="./../simulation/px4_sitl_prebuilt_packages">Docker container or .deb package</a> instead.</p></div><p>The <em>supported platforms</em> for PX4 development are:</p><ul><li><a href="./../dev_setup/dev_env_linux_ubuntu">Ubuntu Linux (24.04/22.04)</a></li><li><a href="./../dev_setup/dev_env_windows_wsl">Windows (10/11)</a> — via WSL2</li><li><a href="./../dev_setup/dev_env_mac">macOS</a></li></ul><h2 id="지원-대상" tabindex="-1">지원 대상 <a class="header-anchor" href="#지원-대상" aria-label="Permalink to &quot;지원 대상&quot;">​</a></h2><p>아래 표는 각 OS에서 구축 가능한 PX 대상을 보여줍니다.</p><table tabindex="0"><thead><tr><th>대상</th><th style="text-align:center;">Linux (Ubuntu)</th><th style="text-align:center;">macOS</th><th style="text-align:center;">윈도우</th></tr></thead><tbody><tr><td><strong>NuttX based hardware:</strong> <a href="./../flight_controller/pixhawk_series">Pixhawk Series</a>, <a href="./../complete_vehicles_mc/crazyflie2">Crazyflie</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><strong>Linux-based hardware:</strong> <a href="./../flight_controller/raspberry_pi_navio2">Raspberry Pi 2/3</a></td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;"></td></tr><tr><td><strong>Simulation:</strong> <a href="./../sim_gazebo_gz/">Gazebo SITL</a></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><strong>Simulation:</strong> ROS 2 with Gazebo</td><td style="text-align:center;">✓</td><td style="text-align:center;"></td><td style="text-align:center;">✓</td></tr><tr><td><strong>Simulation:</strong> <a href="./../sim_gazebo_classic/">Gazebo Classic SITL</a></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td><td style="text-align:center;">✓</td></tr><tr><td><strong>Simulation:</strong> <a href="./../simulation/ros_interface">ROS with Gazebo Classic</a></td><td style="text-align:center;"></td><td style="text-align:center;"></td><td style="text-align:center;">✓</td></tr></tbody></table><p>Experienced Docker users can also build with the containers used by our continuous integration system: <a href="./../test_and_ci/docker">Docker Containers</a></p><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p>위의 명령줄 도구 모음 중 하나를 설정하고, 다음 단계를 실행합니다.</p><ul><li>Install <a href="./../dev_setup/vscode">VSCode</a> (if you prefer using an IDE to the command line).</li><li>Install the <a href="./../dev_setup/qgc_daily_build">QGroundControl Daily Build</a></li><li>Continue to <a href="./../dev_setup/building_px4">Building PX4 Software</a>.</li></ul>',11)])])}const g=e(i,[["render",l]]);export{h as __pageData,g as default};
